package com.aadil.jobtracker.responses;import lombok.AllArgsConstructor;import lombok.Getter;import lombok.Setter;import java.util.List;@Getter@Setter@AllArgsConstructorpublic class PagedResponse<T> {    private final List<T> contents;    private final int page;    private final int pageSize;    private final int totalPage;    private final long totalElements;    private final boolean isLast;}